+#ifndef CPU_MICRO_GEMM_INT8_VSX_HPP
+#define CPU_MICRO_GEMM_INT8_VSX_HPP
+
+#include <algorithm>
+#include <cstdint>
+#include <cstring>
+#include <type_traits>
+#include <utility>
+
+#include "cpu/micro_gemm/cpu_micro_gemm_impl.hpp"
